const items = $input.all();

return items.map(item => {
  let data = item.json;

  // Handle AI Agent output stored as a JSON string
  if (typeof data.output === "string") {
    data = JSON.parse(data.output);
  } else if (data.output && typeof data.output === "object") {
    data = data.output;
  }

  const modules = data.module_grades;

  if (!Array.isArray(modules) || modules.length === 0) {
    throw new Error("module_grades is missing or empty. Check AI Agent output.");
  }

  const finalGrade = modules.reduce((total, module) => {
    const grade = parseFloat(module.grade);
    const weight = parseFloat(module.weight);

    if (isNaN(grade) || isNaN(weight)) {
      throw new Error("Invalid grade or weight in module_grades.");
    }

    return total + (grade * weight / 100);
  }, 0);

  return {
    json: {
      ...data,
      final_grade: finalGrade.toFixed(1) + "%"
    }
  };
});
